def normalize_existing_data(apps, schema_editor):
    """Backfill canonical phones, rename Approved, and protect the new index."""
    Student = apps.get_model('admissions', 'Student')
    PaymentClaim = apps.get_model('admissions', 'PaymentClaim')
    StatementRow = apps.get_model('admissions', 'StatementRow')

    PaymentClaim.objects.filter(status='APPROVED').update(status='CONFIRMED')

    for model, source_field in (
        (Student, 'parent_phone'),
        (PaymentClaim, 'payer_phone'),
        (StatementRow, 'sender_phone'),
    ):
        normalized_field = {
            'parent_phone': 'parent_phone_normalized',
            'payer_phone': 'payer_phone_normalized',
            'sender_phone': 'sender_phone_normalized',
        }[source_field]
        for pk, phone in model.objects.values_list('pk', source_field).iterator():
            normalized = normalize_phone(phone)
            if normalized:
                model.objects.filter(pk=pk).update(**{normalized_field: normalized})

    # The new partial unique index must not fail because an older database
    # already contains duplicates. Keep the earliest claim and detach the
    # transaction ID from later duplicates so an accountant can review them.
    seen = {}
    duplicates = (
        PaymentClaim.objects.exclude(status='REJECTED')
        .exclude(transaction_id='')
        .order_by('submitted_at', 'pk')
        .values_list('pk', 'transaction_id')
    )
    for pk, txn in duplicates.iterator():
        if txn in seen:
            PaymentClaim.objects.filter(pk=pk).update(
                transaction_id='',
                status='NEEDS_REVIEW',
                match_reason=f'Duplicate transaction ID {txn}; detached during upgrade.',
            )
        else:
            seen[txn] = pk


def backfill_receipts_and_credits(apps, schema_editor):
    """Issue receipts for historical payments and persist known overpayments."""
    Student = apps.get_model('admissions', 'Student')
    Payment = apps.get_model('admissions', 'Payment')
    Receipt = apps.get_model('admissions', 'Receipt')
    Credit = apps.get_model('admissions', 'Credit')
    Allocation = apps.get_model('admissions', 'Allocation')

    for payment in Payment.objects.select_related('student__grade').iterator():
        if Receipt.objects.filter(payment_id=payment.pk).exists():
            continue
        student = payment.student
        allocations = Allocation.objects.filter(payment_id=payment.pk, reversed=False)
        Receipt.objects.create(
            id=f'receipt-{payment.pk}',
            receipt_no=f'RCPT-{payment.pk}',
            payment_id=payment.pk,
            student_id=student.pk,
            snapshot={
                'student_no': student.application_no,
                'student_name': ' '.join(
                    part for part in [student.first_name, student.middle_name, student.last_name] if part
                ),
                'grade': student.grade.name if student.grade_id else '',
                'amount': str(payment.amount),
                'transaction_id': payment.reference,
                'payment_date': payment.date.isoformat() if payment.date else '',
                'method': payment.method,
                'notes': payment.notes or '',
                'allocations': [
                    {
                        'fee_line_id': a.fee_line_id,
                        'fee_group_name': a.fee_group_name,
                        'fee_item_label': a.fee_item_label,
                        'amount': str(a.amount),
                    }
                    for a in allocations
                ],
            },
            issued_by='system-backfill',
        )

    for student in Student.objects.select_related('grade').iterator():
        total_fees = Decimal('0')
        if student.grade_id:
            for group in student.grade.fee_groups.all():
                for item in group.items.all():
                    total_fees += item.amount
        total_paid = sum(
            (p.amount for p in Payment.objects.filter(student_id=student.pk)),
            Decimal('0'),
        )
        overpaid = total_paid - total_fees
        if overpaid <= 0:
            continue
        latest = Payment.objects.filter(student_id=student.pk).order_by('-date', '-created_at').first()
        Credit.objects.create(
            id=f'credit-{student.pk}',
            student_id=student.pk,
            payment_id=latest.pk if latest else None,
            amount=overpaid,
            remaining_amount=overpaid,
            reason='Overpayment carried forward during Phase 2 upgrade.',
            created_by='system-backfill',
        )


